-- PinAssist route catalogue.
-- Project: Parking Project (uklqyddpntttrcwaimji).
-- Apply once in the Supabase SQL editor. Safe to re-run: existing ids are left unchanged.
--
-- Read: any signed-in user (officer, roc, slg, admin).
-- Write: public.current_role() = 'admin' only.
-- Anonymous and publishable-key requests have no table grant and no RLS policy.
--
-- Seed data is the original peak catalogue. The public routes.js file has been removed.
-- After this is applied, edit public.routes and public.route_locations.
--
-- Column map back to the in-app ROUTES shape:
--   routes.group_name -> group
--   routes.sort_index -> array order of routes (group headings follow first appearance)
--   routes.recommended_under_construction -> recommendedUnderConstruction
--     true shows "Under Construction" on the Recommended sort button.
--     Set false for one route when its recommended order is finished.
--   route_locations."order" -> order (recommended sort; null sorts last)
--   route_locations.detail_long -> detailLong
--   route_locations.sort_index -> array order within the route (tie-break when order matches)
--   route_locations.lat / lng -> lat / lng (null means geocode from query)
--   route_locations.photo -> photo

create table if not exists public.routes (
  id text primary key,
  name text not null,
  group_name text not null,
  period text not null,
  sort_index integer not null,
  recommended_under_construction boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.route_locations (
  id text primary key,
  route_id text not null references public.routes (id) on delete cascade,
  "order" integer,
  name text not null,
  query text not null,
  detail text not null default '',
  detail_long text not null default '',
  lat numeric(9, 6),
  lng numeric(9, 6),
  photo text,
  sort_index integer not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists route_locations_route_id_idx
  on public.route_locations (route_id);

create index if not exists route_locations_route_id_order_idx
  on public.route_locations (route_id, "order");

comment on table public.routes is
  'Peak route headers. Signed-in users can read; only an admin can write.';
comment on table public.route_locations is
  'Stops for a peak route. Signed-in users can read; only an admin can write.';
comment on column public.routes.group_name is
  'Shown as the route group heading. Mapped to ROUTES[].group.';
comment on column public.routes.sort_index is
  'Display order. Lower values come first so group headings match the original list.';
comment on column public.routes.recommended_under_construction is
  'When true, the Recommended sort button shows Under Construction. Set false when that route recommended order is finished. Recommended sorting is unchanged.';
comment on column public.route_locations."order" is
  'Recommended-route sequence. Null sorts after numbered stops.';
comment on column public.route_locations.detail_long is
  'Full restriction text used for expiry. Mapped to detailLong.';
comment on column public.route_locations.sort_index is
  'Position within the route. Breaks ties when two stops share an order value.';

create or replace function public.touch_route_updated_at()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

drop trigger if exists routes_touch_updated_at on public.routes;
create trigger routes_touch_updated_at
  before update on public.routes
  for each row execute procedure public.touch_route_updated_at();

drop trigger if exists route_locations_touch_updated_at on public.route_locations;
create trigger route_locations_touch_updated_at
  before update on public.route_locations
  for each row execute procedure public.touch_route_updated_at();

revoke all on function public.touch_route_updated_at() from public, anon, authenticated;

alter table public.routes enable row level security;
alter table public.route_locations enable row level security;

drop policy if exists "authenticated read routes" on public.routes;
create policy "authenticated read routes"
  on public.routes
  for select
  to authenticated
  using (true);

drop policy if exists "admin insert routes" on public.routes;
create policy "admin insert routes"
  on public.routes
  for insert
  to authenticated
  with check ((select public.current_role()) = 'admin');

drop policy if exists "admin update routes" on public.routes;
create policy "admin update routes"
  on public.routes
  for update
  to authenticated
  using ((select public.current_role()) = 'admin')
  with check ((select public.current_role()) = 'admin');

drop policy if exists "admin delete routes" on public.routes;
create policy "admin delete routes"
  on public.routes
  for delete
  to authenticated
  using ((select public.current_role()) = 'admin');

drop policy if exists "authenticated read route locations" on public.route_locations;
create policy "authenticated read route locations"
  on public.route_locations
  for select
  to authenticated
  using (true);

drop policy if exists "admin insert route locations" on public.route_locations;
create policy "admin insert route locations"
  on public.route_locations
  for insert
  to authenticated
  with check ((select public.current_role()) = 'admin');

drop policy if exists "admin update route locations" on public.route_locations;
create policy "admin update route locations"
  on public.route_locations
  for update
  to authenticated
  using ((select public.current_role()) = 'admin')
  with check ((select public.current_role()) = 'admin');

drop policy if exists "admin delete route locations" on public.route_locations;
create policy "admin delete route locations"
  on public.route_locations
  for delete
  to authenticated
  using ((select public.current_role()) = 'admin');

revoke all on table public.routes from public, anon, authenticated;
revoke all on table public.route_locations from public, anon, authenticated;
grant select, insert, update, delete on table public.routes to authenticated;
grant select, insert, update, delete on table public.route_locations to authenticated;

