insert into public.routes (id, name, group_name, period, sort_index)
select
  r->>'id',
  r->>'name',
  r->>'group',
  r->>'period',
  (r->>'sort_index')::integer
from route_seed_payload, jsonb_array_elements(doc) as r
on conflict (id) do nothing;

insert into public.route_locations (
  id, route_id, "order", name, query, detail, detail_long, lat, lng, photo, sort_index
)
select
  l->>'id',
  r->>'id',
  (l->>'order')::integer,
  l->>'name',
  l->>'query',
  coalesce(l->>'detail', ''),
  coalesce(l->>'detailLong', ''),
  (l->>'lat')::numeric(9, 6),
  (l->>'lng')::numeric(9, 6),
  l->>'photo',
  (l->>'sort_index')::integer
from route_seed_payload,
  jsonb_array_elements(doc) as r,
  lateral jsonb_array_elements(r->'locations') as l
on conflict (id) do nothing;

drop table route_seed_payload;
